/**
 * Niyom client codes come in two formats:
 *   - legacy  NW-001-0025  (clients created before Nov 2026; kept as-is because
 *     Wylth already knows them through SSO)
 *   - current NW0010030    (BSE StAR / Wylth format — no separators allowed)
 * Both are generated by the DB function nw2_generate_client_code; the serial
 * continues across formats for each RM.
 */

const LEGACY = /^NW-(\d{3})-(\d{4})$/i;
const CURRENT = /^NW(\d{3})(\d{4})$/i;

/** The same code in the other format, or null if `q` is not a full client code. */
export function alternateClientCode(q: string): string | null {
  const s = q.trim().toUpperCase();
  let m = LEGACY.exec(s);
  if (m) return `NW${m[1]}${m[2]}`;
  m = CURRENT.exec(s);
  if (m) return `NW-${m[1]}-${m[2]}`;
  return null;
}

/**
 * Extra PostgREST `.or()` clause so a client-code search typed in either
 * format finds the client whichever format their code is stored in.
 * Returns '' when the term is not a full client code.
 */
export function clientCodeOrClause(q: string): string {
  const alt = alternateClientCode(q);
  return alt ? `,client_code.eq.${alt}` : '';
}
